import sys
import hashlib
import os

def compute_fingerprint(data):
    return hashlib.sha256(data).hexdigest()[:32].lower()

def escape_html(text):
    return text.replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')

def main():
    paths = []
    for line in sys.stdin:
        line = line.strip()
        if line:
            paths.append(line)

    template = open('template.html', 'r').read()
    rows = []
    for path in paths:
        try:
            with open(path, 'rb') as f:
                data = f.read()
                fingerprint = compute_fingerprint(data)
                escaped_path = escape_html(path)
                rows.append(f'<tr><td>{escaped_path}</td><td>{fingerprint}</td></tr>')
        except IOError:
            continue

    rows_str = '\n'.join(rows)
    template = template.replace('{{rows}}', rows_str)
    print(template)

if __name__ == '__main__':
    main()
